      buffer.write(subagentsConfig.toYaml());
    }
    buffer.write(_jobsYaml());
    buffer.write(_headlessYaml());
    buffer.write(_linksYaml());
    buffer.write(_powerYaml());
    buffer.write(_quotaYaml());
    buffer.write(_outputYaml());
