      expect(reloaded.providerKind, 'openai-completions');
      expect(reloaded.modelId, 'openai/gpt-4o-mini');
      expect(reloaded.baseUrl, 'https://openrouter.ai/api/v1');
      expectTicketSectionsLoaded(reloaded);
    });

