model: openai/gpt-4o-mini
baseUrl: https://openrouter.ai/api/v1
spills:
  enabled: false
  threshold: 4096
  headChars: 3000
  tailChars: 2500
subagents:
  heartbeatMinutes: 5
  stallMinutes: 7
jobs:
  staleHours: 48
  logRetentionDays: 7
headless:
  shellJobDrainMs: 600
  shellJobQuietMs: 300
agent:
  mode: pi
  contextWindowCap: 256000
  misuseBreaker: false
quota:
  badge: true
  ttl_minutes: 30
tui:
  theme: ohmypi-dark
trajectory:
  wireDump: true
waiting:
  waitHeartbeatMinutes: 3
power:
  hold: session
''';

/// Asserts every section of the ticket's file loaded into [config].
