    io.writeln('not saved: $error');
    return;
  }
  if (await _env.writeFile(path, edited) is Err) {
    io.writeln('could not write $path');
    return;
  }
  io.writeln('$message → $path (${applicationNote('models')})');
  await _applyCapabilityEdit(segments[2], segments[3]);
}

