  /// stays minimal (defaults are never written). Empty at the defaults,
  /// so [CliConfig.toYaml] embeds it only when explicitly configured
  /// (gh-1572: the section used to be unrenderable and silently dropped
  /// by every save).
  String toYaml() {
    if (enabled &&
        threshold == 8192 &&
        headChars == 2000 &&
        tailChars == 2000) {
