  /// booleans/numbers are accepted, mistyped scalars fall back to the
  /// default with a note, unknown keys are noted and ignored, and a

{"path":"test/cli/_scratch_gh1572_removal_repro_test.dart","content":"// SCRATCH review repro — deleted after the review. Simulates:
// boot -> settings-hub removal flow writes file directly
// (_clearContextCap / _dropAutoUpdateKey) -> later persistConfig-shaped
// saveCliConfig(saved.copyWith(...)) in the SAME session.
import 'dart:io';

import 'package:flutter_agent_harness/flutter_agent_harness.dart';
import 'package:test/test.dart';

String _dropTopLevelBlock(String source, String key) {
  final lines = source.split('\n');
  final start = lines.indexWhere((line) => line.startsWith('$key:'));
  if (start < 0) return source;
  var end = start + 1;
  while (end < lines.length &&
      (lines[end].isEmpty ||
          lines[end].startsWith(' ') ||
          lines[end].startsWith('\t'))) {
    end++;
  }
  return [...lines.sublist(0, start), ...lines.sublist(end)].join('\n');
}

void main() {
  late Directory tmp;

  setUp(() {
    tmp = Directory.systemTemp.createTempSync('fah-gh1572-repro-');
  });
  tearDown(() {
    tmp.deleteSync(recursive: true);
  });

  test('settings-hub clear of agent.cap survives the next persist?', () async {
    final f = File('${tmp.path}/.fah/config.yaml')
      ..createSync(recursive: true)
      ..writeAsStringSync(
        'provider: openai-completions\n'
        'model: openai/gpt-4o-mini\n'
        'baseUrl: https://openrouter.ai/api/v1\n'
        'agent:\n'
        '  contextWindowCap: 256000\n'
        'auto_update: false\n',
      );
    final saved = loadCliConfig(tmp.path);
    expect(saved.contextWindowCap, 256000);

    // _clearContextCap: drops the whole agent: block from the FILE
    // (settings_flow.dart) — the sanctioned removal path.
    final dropped = _dropTopLevelBlock(f.readAsStringSync(), 'agent');
    f.writeAsStringSync(dropped);
    expect(loadCliConfig(tmp.path).contextWindowCap, isNull,
        reason: 'the clear landed on disk');

    // Any later persist trigger in the same session: /mode switch etc.
    await saveCliConfig(
      tmp.path,
      saved.copyWith(
        mode: 'code',
        approvalMode: 'yolo',
        allowedTools: const [],
      ),
    );
    final reloaded = loadCliConfig(tmp.path);
    // BEFORE the fix the user's removal stuck; after gh-1572 the stale
    // boot snapshot re-renders it:
    expect(
      reloaded.contextWindowCap,
      isNull,
      reason: 'user cleared agent.contextWindowCap in settings; '
          'the next save resurrected it from the boot snapshot',
    );
  });

  test('settings-hub auto_update drop survives the next persist?', () async {
    final f = File('${tmp.path}/.fah/config.yaml')
      ..createSync(recursive: true)
      ..writeAsStringSync(
        'provider: openai-completions\n'
        'model: openai/gpt-4o-mini\n'
        'baseUrl: https://openrouter.ai/api/v1\n'
        'auto_update: false\n',
      );
    final saved = loadCliConfig(tmp.path);
    expect(saved.autoUpdate, AutoUpdateMode.off);

    // _dropAutoUpdateKey (cycling off -> notify): removes the key line.
    final dropped = _dropTopLevelBlock(f.readAsStringSync(), 'auto_update');
    f.writeAsStringSync(dropped);
    expect(loadCliConfig(tmp.path).autoUpdate, AutoUpdateMode.notify);

    // Later persist trigger in the same session.
    await saveCliConfig(
      tmp.path,
      saved.copyWith(
        mode: 'code',
        approvalMode: 'yolo',
        allowedTools: const [],
      ),
    );
    final reloaded = loadCliConfig(tmp.path);
    expect(
      reloaded.autoUpdate,
      AutoUpdateMode.notify,
      reason: 'user cycled auto_update off->notify; the next save '
          're-rendered auto_update: false from the boot snapshot',
    );
  });
}
"}

