void _warnCapNoOp(String value) {
  final cap = int.tryParse(value);
  final window = _agent.state.model.contextWindow;
  if (cap != null && window > 0 && cap >= window) {
    io.writeln('note: $cap ≥ model window $window — the cap clamps nothing');
