    // BEFORE the fix the user's removal stuck; after gh-1572 the stale
    // boot snapshot re-renders it:
    expect(
      reloaded.contextWindowCap,
      isNull,
      reason: 'user cleared agent.contextWindowCap in settings; '
          'the next save resurrected it from the boot snapshot',
    );
  });

