Future<void> _applyCompactionEngineScope(
  CompactionEngine engine,
  String scope,
) async {
  if (scope == 'session') {
    config.liveCompactionEngine = engine;
    io.writeln(
      'compaction engine → ${engine.value} (this session; applies at '
