        // `default` is legal and explicit — the written file stays
        // parseable.
        final error = agentLoadModeValidationError(entry.value);
        if (error != null) throw ConfigException(error);
      default:
        throw ConfigException('unknown "agent" key: $key');
    }
  }
}

