// SCRATCH review repro — deleted after the review. The PR's emitter
// renders `agent.misuseBreaker: false`; validateAgentSection (the mirror
// validator used by `fa config check`, `fa config set agent.*` and the
// settings-hub agent upserts) must accept what fa itself writes.
import 'package:flutter_agent_harness/flutter_agent_harness.dart';
import 'package:test/test.dart';
import 'package:yaml/yaml.dart';

void main() {
  test('validateAgentSection accepts the block the gh-1572 emitter renders',
      () {
    const rendered = 'agent:\n'
        '  misuseBreaker: false\n';
    final doc = loadYaml(rendered);
    expect(
      () => validateAgentSection((doc as YamlMap)['agent']),
      returnsNormally,
      reason: 'fa writes this block itself after gh-1572; the strict '
          'validator used by config check/set and the settings hub must '
          'accept it',
    );
  });
}

