    io.writeln('memory: no user config on this host — not saved');
    return;
  }
  final answer = await _askLine(
    "${isProject ? 'project' : 'user'} memory path (empty keeps "
    "'${_memoryPathLabel(project: isProject)}'): ",
  );
  if (answer == null) return;

