Future<bool> _upsertConfigYaml(
  List<String> segments,
  String value, {
  required bool projectScope,
  void Function(Object? node)? validate,
  void Function(YamlMap doc)? validateDoc,
  String? note,
}) async {
  final path = projectScope
      ? '${_env.cwd}/.fah/config.yaml'
      : _userConfigPath()!;
  final read = await _env.readTextFile(path);
  final String source;
  switch (read) {
    case Ok(:final value):
      source = value;
    case Err(:final error) when error.code == FileErrorCode.notFound:
      source = '';
    case Err(:final error):
      io.writeln('cannot read $path: $error — not saved');
      return false;
  }
  final edited = upsertYamlPath(
    source,
    segments,
    configLeafLines(value, depth: segments.length - 1),
  );
  // Never persist a file the next boot would reject.
  final doc = loadYaml(edited);
  final section = doc is YamlMap ? doc[segments.first] : null;
  try {
    validate?.call(section);
    if (doc is YamlMap) validateDoc?.call(doc);
  } on Object catch (error) {
    io.writeln('not saved: $error');
    return false;
  }
  if (await _env.writeFile(path, edited) is Err) {
    io.writeln('could not write $path');
    return false;
  }
  io.writeln(
    '${segments.join('.')} = $value → $path '
    '(${note ?? applicationNote(segments.first)})',
  );
  return true;

{"content":"// SCRATCH review repro — deleted after the review. The PR's emitter
// renders `agent.misuseBreaker: false`; validateAgentSection (the mirror
// validator used by `fa config check`, `fa config set agent.*` and the
// settings-hub agent upserts) must accept what fa itself writes.
import 'package:flutter_agent_harness/flutter_agent_harness.dart';
import 'package:test/test.dart';
import 'package:yaml/yaml.dart';

void main() {
  test('validateAgentSection accepts the block the gh-1572 emitter renders',
      () {
    const rendered = 'agent:\n'
        '  misuseBreaker: false\n';
    final doc = loadYaml(rendered);
    expect(
      () => validateAgentSection((doc as YamlMap)['agent']),
      returnsNormally,
      reason: 'fa writes this block itself after gh-1572; the strict '
          'validator used by config check/set and the settings hub must '
          'accept it',
    );
  });
}
","path":"test/cli/_scratch_misuse_breaker_validator_test.dart"}

