/// (AC3). Loops until cancelled or done.
Future<void> startTtsrRulesFlow() async {
  final path = _userConfigPath();
  if (path == null) {
    io.writeln('ttsr: no user config on this host — not saved');
    return;
  }
  for (;;) {
    final current = await _readTtsrSection(path);
