    late Directory tmp;
    late LocalExecutionEnv env;

    setUp(() {
      tmp = Directory.systemTemp.createTempSync('fah-gh1572-persist-');
      env = LocalExecutionEnv(cwd: tmp.path);
    });

    tearDown(() {
      tmp.deleteSync(recursive: true);
    });

