    /// snapshot as the copyWith base, only the session-live overlays on
    /// top.
    Future<void> persistShapedSave(CliConfig snapshot) => saveCliConfig(
      tmp.path,
      snapshot.copyWith(
        mode: 'code',
        approvalMode: 'yolo',
        allowedTools: const [],
