Future<void> startMcpServersFlow() async {
  final path = _userConfigPath();
  if (path == null) {
    io.writeln('mcp: no user config on this host — not saved');
    return;
  }
  for (;;) {
    if (!await _mcpMenuRound(path)) return;
  }
