provider: openai-completions
model: openai/gpt-4o-mini
baseUrl: https://openrouter.ai/api/v1
spills:
  enabled: false
  threshold: 4096
  headChars: 3000
  tailChars: 2500
subagents:
  heartbeatMinutes: 5
  stallMinutes: 7
jobs:
