      final text = File(configFile(tmp).path).readAsStringSync();
      expect(
        text,
        contains('providersQueue:\n  - name: kimi_me\n    provider: kimi\n'),
        reason: 'the raw queue block must survive a whole-file save',
      );
    });
  });
}

