        },
        cancelOnError: true,
      );
      await Future<void>.delayed(const Duration(milliseconds: 100));
      await saveCliConfig(
        tmp.path,
        saved.withCustomProviders(saved.customProviders),
      );
      await Future<void>.delayed(const Duration(milliseconds: 100));
      await subscription.cancel();

